/* Dialogue portrait IDs are ordered identically by physical portrait slot in
 * all four targets. Each ROM's portrait table independently declares 0xB8
 * entries; its program references resolve to A4NJ:0x2B3AE0,
 * A4NE:0x52D984, BFGE:0x4C4A44, and BFGJ:0x4C64B4. Character ownership is
 * confirmed primarily from SetTalkNameplateCharacter / SetTalkPortrait call-site
 * pairs and the corresponding family source tables. Decoded portrait images are
 * only supporting clues because the current extraction path is known to produce
 * incorrect output for some entries; they are never accepted as independent
 * proof. Expression and costume suffixes are retained only where script context
 * or another independent mapping supports the visual interpretation. The
 * Lou/Ruby character occupies slots
 * 94-97 and Van occupies
 * 141-144 in all four targets. The four GBA ROMs spell this same character's
 * name differently by language/release. Both Japanese GBA ROMs use the actual
 * Japanese spelling `ルウ`. FoMT-US uses `Lou` consistently in its character
 * name table and dialogue (including "My name's Lou."), while MFoMT-US uses
 * `Ruby` consistently (including "The name's Ruby."). The numeric character ID
 * remains 34 and the portrait range remains 94-97 in both games, so these are
 * two English localizations of one character, not two indexed characters.
 *
 * In North American release order, FoMT-US was the character's first English
 * localization and used `Lou`. AWL-US subsequently changed the English name to
 * `Ruby`; MFoMT-US, Another Wonderful Life, A Wonderful Life Special Edition,
 * Harvest Moon DS, and Harvest Moon DS Cute then followed that `Ruby` naming.
 * The DS games apply it to their later-era counterpart/descendant. Thus the old
 * English localization sequence is: first `Lou` in FoMT-US, then `Ruby` from
 * AWL-US onward through MFoMT and the DS-era works.
 *
 * The official English Story of Seasons remakes of Friends of Mineral Town
 * (2020) and A Wonderful Life (2023) both return to and standardize `Lou`.
 * XSEED's localization blog
 * documents that the remake staff deliberately reconsidered legacy character
 * names; the modern choice must therefore not be described as simply forgetting
 * `Ruby`. `Lou` is an attested English localization name, not a spelling inferred
 * here from `ルウ`. Mary-C deliberately uses the neutral combined symbol
 * `LOU_OR_RUBY` so generated source preserves both attested English names without
 * declaring either localization universally canonical.
 * Sources checked 2026-09-02:
 * https://www.gamingalexandria.com/gc/Harvest%20Moon%20A%20Wonderful%20Life/Harvest%20Moon%20A%20Wonderful%20Life%20-%20Clearscan.pdf
 * https://www.storyofseasons.com/fomt/welcometotown/Lou.php
 * https://www.storyofseasons.com/awl/townsfolk/
 * https://www.xseedgames.com/2023/05/04/story-of-seasons-a-wonderful-life-localization-blog-1/
 * https://fogu.com/hm6/chan7/vanabuse.php
 *
 * 四个目标版本的对话头像 ID 均按相同的物理头像槽顺序排列，各 ROM 的立绘表
 * 均独立声明 0xB8 项；程序引用解析到 A4NJ:0x2B3AE0、A4NE:0x52D984、
 * BFGE:0x4C4A44、BFGJ:0x4C64B4。人物归属由 SetTalkNameplateCharacter/SetTalkPortrait
 * 调用配对及相应版本族源码表作为主要依据。当前图片提取流程已知会对部分项目
 * 产生错误输出，因此解包立绘只能作为辅助线索，绝不能独立证明编号语义。表情
 * 与服装后缀仅在脚本上下文或另一份独立映射能够支持视觉解释时保留。四版本的
 * 94-97 槽均属于 Lou／Ruby，
 * 141-144 槽均属于 Van。两个日版 GBA ROM 的实际日文名均为 `ルウ`。FoMT-US 的
 * 人物姓名表和对话始终使用 `Lou`（包括 “My name's Lou.”），MFoMT-US 的姓名表
 * 和对话则始终使用 `Ruby`（包括 “The name's Ruby.”）。两版人物数字 ID 都是 34，
 * 头像范围也都是 94-97，因此这是同一人物的两套英文本地化，不是两个索引人物。
 *
 * 按北美发售顺序，FoMT-US 是该人物第一次进入英文本地化，最初采用 `Lou`。
 * 随后的 AWL-US 将英文名改为 `Ruby`；MFoMT-US、《Another Wonderful Life》、
 * 《A Wonderful Life Special Edition》《Harvest Moon DS》和《Harvest Moon
 * DS Cute》又继续沿用 `Ruby`。DS 两作是在其后世对应人物／后代上使用该名。
 * 因此旧英文版的沿革是：FoMT-US 首次采用 `Lou`，从 AWL-US 开始改用 `Ruby`，
 * 女孩版及 DS 时代作品继续沿用 `Ruby`。
 *
 * 官方英文《Story of Seasons: Friends of Mineral Town》（2020）与《Story of
 * Seasons: A Wonderful Life》（2023）两部重制版均重新采用并统一为 `Lou`。
 * XSEED 的本地化
 * 文章说明团队会有意识地重新讨论旧人物名，故不能把现代选择简单描述成“忘记了
 * Ruby”。`Lou` 是游戏实际采用过的英文名，并非本项目从 `ルウ` 自行音译。Mary-C
 * 特意采用中立组合符号 `LOU_OR_RUBY`，同时保留两套已有英文名，不宣布其中任一套
 * 在所有历史版本中绝对规范。来源链接见上。 */
