/* FoMT-US and MFoMT-US display 0x86 and 0x89 with the same official localized
 * name, "Fried Noodles", and even reuse the same name/description pointers.
 * The JP tables distinguish 焼きうどん at 0x86 from 焼きそば at 0x89; the
 * physical recipe identity therefore uses the descriptive English symbol
 * ITEM_FOOD_FRIED_BUCKWHEAT_NOODLES.
 *
 * FoMT-US 与 MFoMT-US 把 0x86、0x89 都显示为官方本地化名称“Fried Noodles”，
 * 甚至复用同一组名称／说明指针。日版表则明确区分 0x86 的“焼きうどん”和
 * 0x89 的“焼きそば”，因此物理菜谱身份使用描述性的英文符号
 * ITEM_FOOD_FRIED_BUCKWHEAT_NOODLES。 */

/*
 * Ordered IDs used by the supermarket's staple-product quantity purchase
 * interface. Script calls and product dialogue confirm the same order in
 * FoMT-US, FoMT-JP, MFoMT-US, and MFoMT-JP.
 *
 * 杂货店常备商品数量购买界面使用的有序 ID。四个目标版本的脚本调用及商品
 * 对话共同确认了相同顺序。
 */
typedef enum MarySupermarketItemId
{
    SUPERMARKET_ITEM_RICE_BALL = 0,
    SUPERMARKET_ITEM_BREAD = 1,
    SUPERMARKET_ITEM_OIL = 2,
    SUPERMARKET_ITEM_FLOUR = 3,
    SUPERMARKET_ITEM_CURRY_POWDER = 4,
    SUPERMARKET_ITEM_DUMPLING_POWDER = 5,
    SUPERMARKET_ITEM_CHOCOLATE = 6,
} MarySupermarketItemId;

/*
 * Name-entry target kinds shared by all four targets. MFoMT-JP independently
 * uses 1 for newborn cows, 2 for newborn sheep, 3 for newborn chickens, and
 * 4 for childbirth naming; its native callable at raw slot 0x0A6 enters the
 * same name-entry task used by the other three ROMs.
 *
 * 四个目标版本共用的命名输入目标类型。MFoMT-JP 原始脚本分别以 1 命名新生
 * 牛、2 命名新生羊、3 命名新生鸡、4 命名孩子；其原始槽 0x0A6 的 native
 * callable 也进入与另外三版相同的命名任务。
 */
typedef enum MaryNameEntryKind
{
    NAME_ENTRY_HORSE = 0,
    NAME_ENTRY_COW = 1,
    NAME_ENTRY_SHEEP = 2,
    NAME_ENTRY_CHICKEN = 3,
    NAME_ENTRY_CHILD = 4,
    NAME_ENTRY_SPOUSE_NICKNAME = 5,
} MaryNameEntryKind;

/* The original games have exactly one horse-name target, one child-name
 * target, and one custom spouse-nickname target. All four vanilla script sets
 * select slot zero for those three modes. This symbol describes that proven
 * vanilla singleton slot; it does not claim that native code validates or
 * rejects nonzero injected values.
 *
 * 原版游戏的马名、孩子名及自定义配偶昵称都各自只有一个目标，四套原版脚本在
 * 这三种模式下均选择槽 0。该符号只描述已证实的原版单目标槽，不表示原生代码会
 * 校验或拒绝人为注入的非零值。 */
typedef enum MarySingletonNameEntrySlot
{
    NAME_ENTRY_SINGLETON_SLOT = 0,
} MarySingletonNameEntrySlot;

/* Article IDs 0x00-0x32 are shared by both game families. FoMT continues with
 * its romance keepsakes and fifteen albums through 0x5F. MFoMT instead uses
 * 0x33-0x69 for recipe sheets, GameCube-link collectibles, ten albums, beauty
 * items, farm supplies, the five bachelor keepsakes, and Won's Mystery Ticket;
 * 0x6A is the physical empty sentinel. ITEM_ARTICLE_NOT_PRESENT is the separate
 * script-facing -1 result produced by wrappers such as GetVaseArticleId when
 * that physical empty value is observed. The family-specific
 * tail is confirmed by the official US item text selected by Won's complete
 * held-article switch; the JP script has the identical case layout.
 *
 * 两个游戏族共用 0x00-0x32 的物品 ID。FoMT 随后排列恋爱纪念品和十五张唱片，
 * 直到 0x5F；MFoMT 的 0x33-0x69 则改为菜谱纸、GameCube 联动物品、十张唱片、
 * 美容用品、农场物资、五位男性候选人的纪念品及 Won 的 Mystery Ticket；
 * 0x6A 是物理空值哨兵；ITEM_ARTICLE_NOT_PRESENT 是 GetVaseArticleId 等包装器
 * 发现该物理空值后向脚本返回的另一种 -1 结果。女孩版的专属尾表已经由 Won
 * 完整手持物品分支所选择的官方 US 物品文本确认，JP 脚本也使用完全相同的 case
 * 布局。 */
