/* Map IDs use the engine's 10-bit map field. Spring Mine floors occupy
 * 0x0034-0x0133 and Lake Mine floors occupy 0x0134-0x0233; within either
 * range, the displayed floor number is added to the range base. The ranges
 * and representative floors are independently confirmed by the FoMT-US and
 * FoMT-JP cheat references. The 0x00-0x33 physical location order is confirmed
 * by the FoMT map-header table, FOMT Studio's map table, and matching entrance
 * and ChangeMap call sites in all four script sets. The preserved-location
 * scripts independently prove that the no-map sentinel is 0x0234 in FoMT and
 * 0x023A in MFoMT. Values 0x0234-0x0239 are not presented as MFoMT maps because
 * the current evidence proves the sentinel difference, not six extra maps.
 *
 * 地图 ID 使用引擎的 10 位地图字段。泉矿楼层占 0x0034-0x0133，湖矿楼层占
 * 0x0134-0x0233；两个范围内均以范围起点加显示楼层数。范围及代表楼层已经由
 * FoMT-US 与 FoMT-JP 金手指资料分别确认。0x00-0x33 的物理地点顺序又由 FoMT
 * 地图头表、FOMT Studio 地图表以及四套脚本中一致的入口与 ChangeMap 调用共同
 * 确认。保存位置相关脚本又分别证明：FoMT 的无地图哨兵为 0x0234，MFoMT 则为
 * 0x023A。当前证据只能证明哨兵差异，不能证明中间的 0x0234-0x0239 是六张额外
 * 地图，因此不为它们编造地图名称。 */
/* Mine families used by the procedural mine-floor generator. These values are
 * shared by all four targets and select which 256-floor map range and item
 * rules to use; the separate floor_index argument is zero-based.
 *
 * 程序化矿层生成器使用的矿场类别。四个目标版本共用这些值，用于选择对应的
 * 256 层地图范围及物品规则；配套的 floor_index 参数从 0 开始。 */
typedef enum MaryMineKind
{
    MINE_SPRING = 0,
    MINE_LAKE = 1,
} MaryMineKind;

/* Horse creation presets are shared by all four targets. The native callable
 * converts these stage values to age in days by multiplying by 120.
 *
 * 四个目标版本共用的建马年龄预设。原生 callable 会把阶段值乘以 120，换算
 * 为年龄天数。
 */
typedef enum MaryAnimalHorseAgeStage
{
    ANIMAL_HORSE_AGE_STAGE_FOAL = 0,
    ANIMAL_HORSE_AGE_STAGE_ADULT = 1,
} MaryAnimalHorseAgeStage;

/* Complete fishing-record slot order. The FoMT-US save/RAM record published
 * for the original GBA release is a contiguous 59-entry array beginning with
 * eight non-fish catches, followed by 45 ordinary fish and six fish kings.
 * The independently audited MFoMT-US and MFoMT-JP native record getters use
 * the same 59-entry, eight-byte-per-entry layout and treat slots 53-58 as the
 * fish kings. Names reproduce the official US in-game spellings, including
 * `Fatminnow`, `Brown Hakeling`, and `Jp. Huchen`. Slots 22 and 37 are distinct
 * physical records that are both displayed as `Silver Carp`; numeric suffixes
 * preserve that distinction without inventing a species identity.
 *
 * 完整的钓鱼纪录槽顺序。GBA 原版 FoMT-US 的存档／内存纪录是一组连续 59 项：
 * 前八项是非鱼类钓获物，随后是 45 种普通鱼及六种鱼王。独立审计的
 * MFoMT-US、MFoMT-JP 原生纪录 getter 使用相同的 59 项、每项八字节布局，
 * 并把 53-58 作为鱼王。名称保留 US 游戏实际显示拼写，包括 `Fatminnow`、
 * `Brown Hakeling` 和 `Jp. Huchen`。槽 22 与 37 是两个不同物理纪录，但画面
 * 都显示 `Silver Carp`；数字后缀只用于区分物理槽，不猜测另一物种名称。
 */
