/* Tool IDs are kept in physical numeric order and currently treated as one
 * shared table across all four targets. ITEM_TOOL_NOT_PRESENT is the script-facing
 * -1 result returned by GetPlayerHeldToolId for an empty held-tool stack; it
 * is distinct from the physical ITEM_TOOL_NONE table member. The source tables, FoMT-US and FoMT-JP
 * cheat reference tables, and MFoMT-JP curse-removal flow provide independent
 * evidence for this layout; any later proven target difference should narrow
 * only the affected member.
 *
 * 工具 ID 按物理编号顺序排列，当前视为四个目标版本共用同一张表。
 * ITEM_TOOL_NOT_PRESENT 是 GetPlayerHeldToolId 在手持工具堆为空时返回给脚本的 -1，
 * 与物理表成员 ITEM_TOOL_NONE 不同。源码表、
 * FoMT-US/FoMT-JP 金手指资料以及 MFoMT-JP 解除诅咒流程分别为该布局提供了
 * 证据；后续若证实某目标存在差异，只对相应成员缩小定义范围。 */
