/* Unknown multi-bit slots intentionally have no mary_var_type binding. A
 * comparison with one lifecycle constant in the global event-exclusion guard
 * proves only that one tested numeric value, not that the slot implements the
 * complete MaryEventLifecycleState contract. Keeping raw numbers prevents a
 * plausible-looking but unproven state name from being emitted.
 *
 * 未知的多比特槽有意不绑定 mary_var_type。全局事件互斥条件中与某一个生命
 * 周期常量的比较，只能证明被比较的那个数值，不能证明该槽实现了完整的
 * MaryEventLifecycleState 契约。保留裸数字可避免反编译输出看似合理但未经
 * 证实的状态名。 */

