/* GetAnimalGrowthStage has a species-dependent result domain. These metadata
 * declarations affect only decompiler symbol selection; they compile to no
 * bytecode and leave the callable's physical integer result unchanged.
 *
 * GetAnimalGrowthStage 的返回域取决于动物类别。以下元数据只控制反编译时
 * 选择的符号类型，不生成任何字节码，也不改变 callable 的物理整数返回值。 */
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_HORSE, MaryAnimalPetGrowthStage);
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_COW, MaryAnimalCowGrowthStage);
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_SHEEP, MaryAnimalSheepGrowthStage);
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_CHICKEN, MaryAnimalChickenGrowthStage);
mary_callable_return_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_DOG, MaryAnimalPetGrowthStage);

/* GetPresentedItemId reads the player actor's captured presentation-ID cache.
 * The native producer writes that cache only for FOOD and ARTICLE; inside a
 * branch proven to be either kind, the saved result uses the corresponding
 * complete ID domain. Other presented kinds deliberately remain integer-valued:
 * their HeldItem storage is not proof that this separate cache contains an ID.
 *
 * GetPresentedItemId 读取玩家角色捕获的“提交物品 ID”缓存。原生生产者只在
 * FOOD 与 ARTICLE 流程中写入该缓存；在已证实为这两类之一的分支中，其保存
 * 结果分别使用对应的完整 ID 域。其他提交类别故意保持整数：HeldItem 自身的
 * 存储布局不能证明这项独立缓存中也保存了相应 ID。 */
mary_callable_return_type_when_callable(GetPresentedItemId, GetPresentedItemKind, HELD_ITEM_KIND_FOOD, MaryItemFoodId);
mary_callable_return_type_when_callable(GetPresentedItemId, GetPresentedItemKind, HELD_ITEM_KIND_ARTICLE, MaryItemArticleId);

/* OpenNameEntry's target index is interpreted by the selected naming mode.
 * Cow and sheep names address the shared barn-animal slots, chicken names
 * address the separate chicken slots, and the horse, child, and spouse modes
 * select their proven single vanilla target.
 * These declarations affect decompiler symbol selection only.
 *
 * OpenNameEntry 的目标索引由所选命名模式决定。牛、羊名称使用共用的大动物
 * 槽位，鸡名称使用独立的鸡槽位；马、孩子与配偶模式选择其已证实的原版唯一
 * 目标。以下声明仅影响反编译器选择符号。 */
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_HORSE, 1, MarySingletonNameEntrySlot);
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_COW, 1, MaryAnimalSlotIndex);
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_SHEEP, 1, MaryAnimalSlotIndex);
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_CHILD, 1, MarySingletonNameEntrySlot);
mary_callable_parameter_type_when(OpenNameEntry, 0, NAME_ENTRY_SPOUSE_NICKNAME, 1, MarySingletonNameEntrySlot);

/* The shared livestock handlers use a family-local index. Chicken records
 * occupy the eight-slot coop domain; cow and sheep records occupy the shared
 * sixteen-slot barn domain. The static declarations retain the barn domain as
 * their conservative default, while these metadata bindings recover chicken
 * slot symbols whenever the discriminator proves that family. Contest-entry
 * selectors use their separate FESTIVAL_ANIMAL_* discriminator order.
 *
 * 共用家畜处理函数使用类别内部索引。鸡记录属于八槽鸡舍域，牛羊记录属于共用
 * 的十六槽畜舍域。静态声明以畜舍域作为保守默认值；当判别参数能够证明类别为
 * 鸡时，以下元数据恢复鸡槽位符号。祭典参赛选择器使用另一套
 * FESTIVAL_ANIMAL_* 判别顺序。 */
mary_callable_parameter_type_when(DoesAnimalExist, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalName, 1, ANIMAL_KIND_CHICKEN, 2, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(HasAnimalBeenTalkedTo, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(SetAnimalTalkedTo, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(AddAnimalAffection, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(IsAnimalUnhappy, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(IsAnimalSick, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(IsAnimalPregnant, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalHealthyPregnancyDays, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalAge, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalAffection, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
mary_callable_parameter_type_when(GetAnimalGrowthStage, 0, ANIMAL_KIND_CHICKEN, 1, MaryAnimalChickenSlotIndex);
